type Event = {id:string; kind:"reserve"|"release"; reservation:string; units:number};
export function apply(s:{available:number; seen:Set<string>; held:Map<string,number>}, e:Event) {
  if (s.seen.has(e.id)) return s;
  s.seen.add(e.id);
  if (e.kind === "reserve") { s.available -= e.units; s.held.set(e.reservation,e.units); }
  else { const held = s.held.get(e.reservation) ?? 0; s.available += held; s.held.delete(e.reservation); }
  return s;
}
export const replay = (events:Event[]) => events.reduce(apply,{available:8,seen:new Set<string>(),held:new Map<string,number>()});

